import React, { useState, useEffect } from 'react';
import { getFranchises, updateExamData, deleteExamData } from '../services/api'; // Assuming you've created these functions

const ExamData = () => {
    const [filterFranchiseId, setFilterFranchiseId] = useState('');
    const [franchises, setFranchises] = useState([]);
    const [examDataList, setExamDataList] = useState([]);
    const [editingExam, setEditingExam] = useState(null); // State to track the exam being edited

    useEffect(() => {
        const fetchFranchises = async () => {
            try {
                const response = await getFranchises();
                setFranchises(response.data);
            } catch (error) {
                console.error('Error fetching franchises:', error);
                alert('Failed to fetch franchises');
            }
        };

        fetchFranchises();
    }, []);

    const handleEdit = (exam) => {
        setEditingExam(exam);
    };

    const handleSaveEdit = async (examId, updatedData) => {
        try {
            await updateExamData(examId, updatedData); // Call API to update exam data
            setExamDataList((prevList) =>
                prevList.map((exam) =>
                    exam._id === examId ? { ...exam, ...updatedData } : exam
                )
            );
            setEditingExam(null); // Close the edit mode
        } catch (error) {
            console.error('Error updating exam data:', error);
        }
    };

    const handleDelete = async (examId) => {
        try {
            await deleteExamData(examId); // Call API to delete exam data
            setExamDataList((prevList) => prevList.filter((exam) => exam._id !== examId));
        } catch (error) {
            console.error('Error deleting exam data:', error);
        }
    };

    const filteredExamData = filterFranchiseId
        ? examDataList.filter((exam) => exam.franchiseId === filterFranchiseId)
        : examDataList;

    return (
        <div>
            <h1>Manage Exam Data</h1>
            <div>
                <label htmlFor="filterFranchiseId">Filter by Franchise:</label>
                <select
                    id="filterFranchiseId"
                    value={filterFranchiseId}
                    onChange={(e) => setFilterFranchiseId(e.target.value)}
                >
                    <option value="">All</option>
                    {franchises.map((franchise) => (
                        <option key={franchise._id} value={franchise._id}>
                            {franchise.name}
                        </option>
                    ))}
                </select>
            </div>

            <h2>Exam Data</h2>
            {examDataList.length > 0 ? (
                <table border="1">
                    <thead>
                        <tr>
                            <th>Franchise Name</th>
                            <th>Exam Name</th>
                            <th>Date</th>
                            <th>Students Attended</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredExamData.map((exam) => (
                            <tr key={exam._id}>
                                <td>{exam.franchiseName}</td>
                                <td>{exam.examName}</td>
                                <td>{exam.date}</td>
                                <td>{exam.studentsAttended}</td>
                                <td>
                                    <button onClick={() => handleEdit(exam)}>Edit</button>
                                    <button onClick={() => handleDelete(exam._id)}>Delete</button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            ) : (
                <p>No exam data available for the selected franchise.</p>
            )}

            {editingExam && (
                <div>
                    <h3>Edit Exam Data</h3>
                    <form
                        onSubmit={(e) => {
                            e.preventDefault();
                            handleSaveEdit(editingExam._id, {
                                examName: e.target.examName.value,
                                date: e.target.date.value,
                                studentsAttended: e.target.studentsAttended.value,
                            });
                        }}
                    >
                        <div>
                            <label htmlFor="examName">Exam Name</label>
                            <input
                                type="text"
                                id="examName"
                                defaultValue={editingExam.examName}
                                required
                            />
                        </div>
                        <div>
                            <label htmlFor="date">Date</label>
                            <input
                                type="date"
                                id="date"
                                defaultValue={editingExam.date}
                                required
                            />
                        </div>
                        <div>
                            <label htmlFor="studentsAttended">Students Attended</label>
                            <input
                                type="number"
                                id="studentsAttended"
                                defaultValue={editingExam.studentsAttended}
                                required
                            />
                        </div>
                        <button type="submit">Save Changes</button>
                    </form>
                    <button onClick={() => setEditingExam(null)}>Cancel</button>
                </div>
            )}
        </div>
    );
};

export default ExamData;
